package legacy

import (
	"context"
	"errors"
	"fmt"
	"net/url"
	"strconv"
	"strings"

	"github.com/qdrant/go-client/qdrant"
)

// QdrantClient is a thin wrapper over the qdrant-go client that
// implements QdrantReader. It is used in production to read points
// from the legacy Qdrant. The migrator never writes to Qdrant — the
// new platform's files-svc handler owns the new-Qdrant write
// (Decision 9c: copy, never re-embed; the migrator forwards the
// vector via gRPC, files-svc upserts).
type QdrantClient struct {
	client *qdrant.Client
}

// NewQdrantReader opens a Qdrant gRPC connection. The url accepts the
// same formats used elsewhere in the legacy stack: a bare host, a
// host:port (assumed gRPC port 6334 if no explicit port), or an
// http://host:port URL. Callers must defer Close() to release the
// underlying gRPC connection.
//
// We intentionally accept either an HTTP-style URL (matching the
// legacy stack's QDRANT_URL env var, which is "http://host:6333" by
// convention) or a bare host[:port]. When an HTTP URL is supplied,
// we route to the gRPC port 6334 because the qdrant-go client speaks
// gRPC, not HTTP. Operators can override by passing host:6334
// directly.
func NewQdrantReader(_ context.Context, rawURL string) (*QdrantClient, error) {
	if rawURL == "" {
		return nil, errors.New("legacy: qdrant url required")
	}
	host, port, err := parseQdrantURL(rawURL)
	if err != nil {
		return nil, fmt.Errorf("legacy: parse qdrant url %q: %w", rawURL, err)
	}
	cfg := &qdrant.Config{
		Host:                   host,
		Port:                   port,
		SkipCompatibilityCheck: true,
	}
	c, err := qdrant.NewClient(cfg)
	if err != nil {
		return nil, fmt.Errorf("legacy: dial qdrant %s:%d: %w", host, port, err)
	}
	return &QdrantClient{client: c}, nil
}

// Close releases the underlying gRPC connection. Safe to call multiple
// times.
func (c *QdrantClient) Close() error {
	if c.client == nil {
		return nil
	}
	return c.client.Close()
}

// FetchPoints reads a batch of points from a single legacy Qdrant
// collection by their UUID-string ids, returning the dense vector +
// the embedding model that the legacy stack stamped into the point
// payload (or empty when absent — production usage doesn't read the
// model from Qdrant; the apply layer takes it from the postgres row).
//
// Points that don't exist in the collection are simply omitted from
// the returned slice; callers correlate by point id and emit
// rejection notes for the gap. Multi-vector / sparse-vector points
// are dropped with no error — the legacy stack only ever wrote
// single dense vectors.
func (c *QdrantClient) FetchPoints(ctx context.Context, collection string, pointIDs []string) ([]LegacyEmbeddingPoint, error) {
	if c == nil || c.client == nil {
		return nil, errors.New("legacy: qdrant client is nil")
	}
	if collection == "" {
		return nil, errors.New("legacy: qdrant collection name is required")
	}
	if len(pointIDs) == 0 {
		return nil, nil
	}
	ids := make([]*qdrant.PointId, 0, len(pointIDs))
	for _, raw := range pointIDs {
		if raw == "" {
			continue
		}
		ids = append(ids, qdrant.NewIDUUID(raw))
	}
	if len(ids) == 0 {
		return nil, nil
	}

	withVectors := qdrant.NewWithVectors(true)
	withPayload := qdrant.NewWithPayload(false)
	req := &qdrant.GetPoints{
		CollectionName: collection,
		Ids:            ids,
		WithVectors:    withVectors,
		WithPayload:    withPayload,
	}
	pts, err := c.client.Get(ctx, req)
	if err != nil {
		return nil, fmt.Errorf("legacy: qdrant get points (collection=%s, n=%d): %w", collection, len(ids), err)
	}

	out := make([]LegacyEmbeddingPoint, 0, len(pts))
	for _, p := range pts {
		pointID := p.GetId().GetUuid()
		if pointID == "" {
			// Numeric id case — render to string so callers can
			// still correlate. Legacy stack always issued UUIDs,
			// but the API surface allows num too.
			if num := p.GetId().GetNum(); num != 0 {
				pointID = strconv.FormatUint(num, 10)
			}
		}
		vec := extractDenseVector(p.GetVectors())
		if vec == nil {
			// Either no vectors returned (we asked for them but
			// the collection was created without dense vectors)
			// or this is a sparse/multi-vector point. Skip with
			// no error — apply layer will treat the point as
			// missing.
			continue
		}
		out = append(out, LegacyEmbeddingPoint{
			PointID: pointID,
			Vector:  vec,
		})
	}
	return out, nil
}

// extractDenseVector pulls a single dense []float32 out of the
// VectorsOutput. The legacy stack only ever wrote a single unnamed
// dense vector per point, so we hit the simple case. We tolerate
// multi-vector and named-vector shapes by returning nil — the apply
// layer treats that as "point not found".
func extractDenseVector(v *qdrant.VectorsOutput) []float32 {
	if v == nil {
		return nil
	}
	single := v.GetVector()
	if single != nil {
		// Newer qdrant-go versions express the dense case as a
		// nested *DenseVector; older versions populate .Data
		// directly on VectorOutput.
		if dense := single.GetDense(); dense != nil {
			data := dense.GetData()
			if len(data) > 0 {
				out := make([]float32, len(data))
				copy(out, data)
				return out
			}
		}
		if data := single.GetData(); len(data) > 0 {
			out := make([]float32, len(data))
			copy(out, data)
			return out
		}
	}
	return nil
}

// parseQdrantURL extracts (host, port) from the rawURL forms the
// legacy stack uses. Defaults to gRPC port 6334 when no port is
// supplied — the qdrant-go client speaks gRPC, not HTTP. When the
// URL parses with an http(s) scheme but the port is the HTTP one
// (6333), we still return 6334 so callers don't have to change env
// vars when porting from the legacy QDRANT_URL.
func parseQdrantURL(raw string) (string, int, error) {
	const grpcPort = 6334
	const httpPort = 6333
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return "", 0, errors.New("empty url")
	}
	if strings.Contains(trimmed, "://") {
		u, err := url.Parse(trimmed)
		if err != nil {
			return "", 0, err
		}
		host := u.Hostname()
		if host == "" {
			return "", 0, errors.New("missing host")
		}
		if portStr := u.Port(); portStr != "" {
			p, err := strconv.Atoi(portStr)
			if err != nil {
				return "", 0, fmt.Errorf("bad port %q: %w", portStr, err)
			}
			// If the legacy stack handed us http://host:6333,
			// route to gRPC 6334 instead.
			if p == httpPort {
				return host, grpcPort, nil
			}
			return host, p, nil
		}
		return host, grpcPort, nil
	}
	// host[:port]
	if idx := strings.LastIndex(trimmed, ":"); idx > 0 && idx < len(trimmed)-1 {
		host := trimmed[:idx]
		p, err := strconv.Atoi(trimmed[idx+1:])
		if err != nil {
			return "", 0, fmt.Errorf("bad port %q: %w", trimmed[idx+1:], err)
		}
		return host, p, nil
	}
	return trimmed, grpcPort, nil
}


