// Package legacy contains DTOs for legacy data sources (Postgres + Qdrant + Memgraph).
package legacy

import (
	"context"
	"time"
)

// EntityType is a synthesized taxonomy entry derived from legacy
// Memgraph DISTINCT e.type queries. Legacy doesn't store descriptions,
// colors, or icons — those default to empty.
type EntityType struct {
	Name        string // e.g. "PERSON"
	Description string // empty in legacy
	Color       string // empty in legacy
	Icon        string // empty in legacy
	LegacyID    string // synthesized: "legacy:entity-type:<org_id>:<name>"
}

// RelationshipType is a synthesized relationship taxonomy entry.
type RelationshipType struct {
	Name        string // e.g. "WORKS_AT"
	Description string
	IsDirected  bool   // all legacy relationships are directed
	LegacyID    string // synthesized: "legacy:rel-type:<org_id>:<name>"
}

// LegacyCorpus is a row from legacy `document_collections` filtered by
// organization_id. Owner is a nullable INTEGER FK to legacy users; the
// new platform stores owner as a UUID, so resolution is deferred to a
// later sub-PR (sub-PR 8 captures the int and emits a rejection note).
type LegacyCorpus struct {
	LegacyID    int64     // legacy document_collections.id
	Name        string    // legacy document_collections.name
	Description string    // legacy document_collections.description (NULL coalesced to "")
	Visibility  string    // "private" | "team" | "shared"
	OwnerUserID *int64    // legacy users.id (nullable)
	CreatedAt   time.Time // legacy document_collections.created_at
}

// CorpusReader is the legacy-Postgres subset for Phase 3 (corpora apply).
// Tests inject a mock; production uses the pgxpool-backed PostgresReader.
type CorpusReader interface {
	ListCorpora(ctx context.Context, legacyOrgID int64) ([]LegacyCorpus, error)
}

// LegacyDocument is a row from legacy `documents` filtered by
// organization_id. The legacy schema stores users.id as INTEGER FK; the
// new platform stores uploaded_by as a UUID, so resolution is deferred
// (Phase 4 emits a rejection note and skips the row when uploaded_by is
// nil — files-svc's MigrateUpload requires a non-empty uploaded_by).
//
// FilePath is the legacy `documents.file_path` column verbatim. Phase 4
// resolves the on-disk file as `${LEGACY_DOCS_DIR}/<file_path>` (or as
// an absolute path when FilePath is already absolute). MIMEType is
// derived from the legacy `file_type` column (e.g. "pdf" → resolved to
// a media type by the apply layer; the mapper passes the raw value
// through).
type LegacyDocument struct {
	LegacyID           int64     // legacy documents.id
	LegacyCollectionID int64     // legacy document_collections.id (the corpus)
	FilePath           string    // legacy documents.file_path (relative or absolute)
	OriginalFilename   string    // legacy documents.filename (or title fallback)
	MIMEType           string    // resolved media type, e.g. "application/pdf"
	SizeBytes          int64     // legacy documents.file_size (NULL → 0)
	UploadedBy         *int64    // legacy documents.uploaded_by (nullable)
	CreatedAt          time.Time // legacy documents.created_at
}

// DocumentReader is the legacy-Postgres subset for Phase 4 (documents
// apply). Tests inject a mock; production uses the pgxpool-backed
// PostgresReader.
type DocumentReader interface {
	ListDocuments(ctx context.Context, legacyOrgID int64) ([]LegacyDocument, error)
}

// LegacyChunk is a row from legacy `document_chunks` belonging to a
// single legacy document. The legacy schema has no per-row
// organization_id; chunks are scoped via documents.organization_id.
//
// The new platform's `MigrateChunkRow` only carries chunk_index, text,
// start_char, end_char, and legacy_id. Phase 5 ignores embedding_id,
// embedding_model, and embedding_dimension (Phase 6 handles those).
// chunk_metadata is intentionally not propagated — the new schema does
// not store per-chunk JSON metadata at this layer; if downstream phases
// need a heading/section we capture it separately later.
type LegacyChunk struct {
	LegacyID         int64     // legacy document_chunks.id
	LegacyDocumentID int64     // legacy document_chunks.document_id
	ChunkIndex       int32     // legacy document_chunks.chunk_index
	Content          string    // legacy document_chunks.content
	StartChar        *int32    // legacy document_chunks.start_char (nullable)
	EndChar          *int32    // legacy document_chunks.end_char (nullable)
	CreatedAt        time.Time // legacy document_chunks.created_at
}

// ChunkReader is the legacy-Postgres subset for Phase 5 (chunks apply).
// Tests inject a mock; production uses the pgxpool-backed
// PostgresReader. Chunks are read per legacy document id (the migrator
// drives iteration off the document_legacy_id_map sidecar produced in
// Phase 4) and returned ordered by chunk_index ASC.
type ChunkReader interface {
	ListChunksByDocument(ctx context.Context, legacyDocumentID int64) ([]LegacyChunk, error)
}

// LegacyChunkEmbeddingRef is a Postgres-side hint that points Phase 6 at
// the legacy Qdrant point for a given chunk. Each row carries:
//
//   - LegacyChunkID         the source-of-truth integer id from legacy
//                           `document_chunks.id`.
//   - LegacyDocumentID      the chunk's document (for iteration off
//                           document_map.json).
//   - ChromaID              the legacy `document_chunks.chroma_id`
//                           column — despite its historical name this
//                           is the Qdrant point id (UUID string) the
//                           legacy stack issued when it upserted the
//                           vector. Phase 6 reads the legacy Qdrant
//                           point by this id.
//   - VectorCollectionName  the legacy
//                           `document_collections.vector_collection_name`
//                           — there is one Qdrant collection per legacy
//                           corpus, not a single global collection. We
//                           must join to discover the name.
//   - EmbeddingModel        the legacy
//                           `document_chunks.embedding_model` column,
//                           pinned per Decision 9c. Forwarded verbatim
//                           in MigrateChunkEmbedding.embedding_model.
//
// Rows where chroma_id is NULL/empty or the joined collection name is
// empty are dropped server-side — they have no legacy Qdrant point to
// copy and would be rejected by the apply layer anyway.
type LegacyChunkEmbeddingRef struct {
	LegacyChunkID        int64
	LegacyDocumentID     int64
	ChromaID             string // legacy Qdrant point id (UUID string)
	VectorCollectionName string // per-corpus legacy Qdrant collection
	EmbeddingModel       string // pinned legacy embedding model
}

// EmbeddingRefReader is the legacy-Postgres subset for Phase 6
// (embeddings apply). For each legacy document id, we read every
// `document_chunks` row with a non-NULL `chroma_id` joined to its
// `document_collections.vector_collection_name`, ordered by chunk_index
// ASC. Tests inject a mock; production uses the pgxpool-backed
// PostgresReader.
type EmbeddingRefReader interface {
	ListEmbeddingRefsByDocument(ctx context.Context, legacyDocumentID int64) ([]LegacyChunkEmbeddingRef, error)
}

// LegacyEmbeddingPoint is one legacy Qdrant point pulled by Phase 6.
//
// PointID is the original `chroma_id` (preserved verbatim — though we
// do not preserve it in the new Qdrant; the new platform's
// MigrateChunkEmbeddings handler issues a fresh point id). Vector is
// the dense embedding floats. EmbeddingModel is forwarded for the
// proto's informational field (the legacy stack pinned it per chunk).
type LegacyEmbeddingPoint struct {
	PointID        string // legacy Qdrant point id (UUID string)
	Vector         []float32
	EmbeddingModel string // forwarded from the postgres row
}

// LegacyChunkEmbedding pairs a legacy chunk identity with the fetched
// Qdrant vector. This is what the apply layer feeds the mapper after
// joining the postgres ref with the qdrant point.
type LegacyChunkEmbedding struct {
	LegacyChunkID    int64
	LegacyDocumentID int64
	Vector           []float32
	EmbeddingModel   string
}

// LegacyEntity is one Memgraph `:Entity` node belonging to a legacy
// organization. Phase 7 (entities apply) reads these via
// MemgraphReader.ListEntities and forwards them to
// EntityService.MigrateEntity.
//
// Legacy storage shape (verified against the monolith's
// graph_service.create_or_merge_entity):
//
//	MERGE (e:Entity {name: $name, type: $type, organization_id: $org_id})
//	  ON CREATE SET e += $props,
//	                e.created       = localdatetime(),
//	                e.mention_count = 1,
//	                e.source        = $source
//	  ON MATCH  SET e += $props,
//	                e.updated       = localdatetime(),
//	                e.mention_count = coalesce(e.mention_count, 0) + 1
//
// Notable consequences:
//
//   - There is NO stable `legacy_id` property on legacy Entity nodes;
//     the natural key is (name, type, organization_id). Phase 7
//     synthesizes the legacy id from Memgraph's internal node id —
//     "legacy:entity:<int64>" — and persists that mapping in
//     entity_map.json so downstream phases (edges, provenance) can
//     translate references deterministically.
//   - `name` is the human-readable label.
//   - `type` is a free-form string (e.g. "PERSON", "ORGANIZATION")
//     which Phase 1 (entity-types apply) bootstrapped into
//     files.entity_types. Phase 7 must resolve `type` → new
//     entity_type UUID via the entity_type_map.json sidecar.
//   - `created` is a Memgraph LocalDateTime; we expose it as
//     time.Time in UTC. Zero-valued when absent on legacy.
//   - All other Memgraph properties (the `props` map merged in by the
//     legacy stack) are surfaced as Properties (opaque to the mapper);
//     name/type/organization_id are stripped — they are normalized into
//     dedicated fields above.
//
// LegacyCorpusIDs is intentionally left empty for Phase 7. The legacy
// stack does not link entities to corpora directly in Memgraph; the
// only entity↔document link is `(e:Entity)-[:MENTIONED_IN]->(d:Document)`,
// and the document→corpus join lives in Postgres
// (`documents.collection_id`). That join is a Phase 9 (provenance)
// concern and would require both readers — out of Phase 7 scope. The
// field is preserved here for forward compatibility with later
// phases that may opt to backfill corpus membership at entity
// migration time.
type LegacyEntity struct {
	LegacyID        string         // synthesized: "legacy:entity:<int64>"
	Label           string         // legacy `name` property — REQUIRED
	TypeName        string         // legacy `type` property — REQUIRED, resolved via Phase 1 sidecar
	Description     string         // empty in legacy; reserved for future use
	Properties      map[string]any // remaining Memgraph properties, opaque
	CreatedAt       time.Time      // legacy `created` LocalDateTime; zero when absent
	LegacyCorpusIDs []int64        // intentionally empty in Phase 7 — see godoc above
}

// LegacyEdge is one Memgraph relationship between two `:Entity` nodes
// belonging to a legacy organization. Phase 8 (edges apply) reads these
// via MemgraphReader.ListEdges and forwards them to
// EdgeService.MigrateEdge.
//
// Legacy storage shape (verified against the monolith's
// graph_service.create_relationship / create_manual_relationship):
//
//	MATCH (a:Entity {organization_id: $org})
//	MATCH (b:Entity {organization_id: $org})
//	MERGE (a)-[r:WORKS_AT]->(b)        // label is the relationship_type, sanitized
//	  ON CREATE SET r += $props,
//	                r.created    = localdatetime(),
//	                r.confidence = coalesce($props.confidence, 1.0)
//	  ON MATCH  SET r += $props,
//	                r.updated    = localdatetime()
//
// Notable consequences:
//
//   - Legacy stores the relationship type as the Memgraph edge LABEL,
//     not a property — so we read it via type(r) (matches Phase 2's
//     ListRelationshipTypes contract).
//   - There is NO stable `legacy_id` property on legacy edges; the
//     natural key is (a, type, b) but a/b are themselves keyed by their
//     internal node ids in our Phase 7 map. Phase 8 synthesizes the
//     legacy edge id from Memgraph's internal relationship id —
//     "legacy:edge:<int64>".
//   - Source/target are identified by id(a)/id(b) — the same internal
//     node ids Phase 7 used to mint LegacyEntity.LegacyID. The mapper
//     builds "legacy:entity:<int64>" and looks it up in the Phase 7
//     sidecar to get the new entity UUID.
//   - All edge properties (the `props` map merged in by the legacy
//     stack — confidence, source, source_document_id, etc.) are
//     surfaced via Properties (opaque to the mapper). The new platform
//     stores them in entity_edges.properties JSONB verbatim.
//   - `created` is a Memgraph LocalDateTime; we expose it as time.Time
//     in UTC. Zero-valued when absent on legacy.
type LegacyEdge struct {
	LegacyID         string         // synthesized: "legacy:edge:<int64>"
	SourceLegacyID   string         // synthesized: "legacy:entity:<source_internal_id>"
	TargetLegacyID   string         // synthesized: "legacy:entity:<target_internal_id>"
	RelationshipType string         // type(r) — free-form; matches Phase 2 ListRelationshipTypes name
	Properties       map[string]any // remaining Memgraph properties, opaque
	CreatedAt        time.Time      // legacy `created` LocalDateTime; zero when absent
}

// ProvenanceLink is one source↔chunk provenance edge surfaced for
// Phase 9. The `SourceLegacyID` is either an entity legacy_id
// ("legacy:entity:<int64>") or an edge legacy_id
// ("legacy:edge:<int64>") depending on which reader produced it; the
// receiving mapper decides which lookup map to consult.
//
// `ChunkLegacyID` is the legacy chunk id keyed
// "legacy:chunk:<int64>" — matching the sidecar format
// chunk_map.json (Phase 5) emits.
//
// Confidence is forwarded to MigrateProvenance.confidence; legacy
// edges that didn't track a confidence default to 1.0 at the mapper
// layer (the new platform's Postgres column is NOT NULL).
//
// Properties is reserved for future expansion (extra MENTIONED_IN
// metadata like start_char/end_char/context). The proto's
// MigrateProvenance.Link does not currently carry a Struct field, so
// the mapper does not forward these — they're surfaced for symmetry
// with the rest of the migrator and for diagnostic logs.
//
// IMPORTANT — legacy provenance gap:
//
//	Legacy stores entity↔DOCUMENT provenance via the
//	(:Entity)-[:MENTIONED_IN]->(:Document) edge in Memgraph. There is
//	NO entity↔chunk granularity in the legacy schema — entities are
//	linked to whole documents, never to specific chunks. Edges
//	(`:Entity`-[:REL]->`:Entity`) sometimes carry a
//	`source_document_id` property pointing at a document, but never
//	a `source_chunk_id`.
//
//	The new platform's MigrateProvenance API requires chunk-level
//	granularity (entity↔chunk and edge↔chunk). That granularity
//	cannot be derived from legacy without a fan-out heuristic
//	(entity → document → all chunks) which would massively
//	over-state provenance and corrupt confidence scoring.
//
//	Phase 9 therefore implements the readers + mapper + apply
//	plumbing END-TO-END but the bolt readers return EMPTY slices and
//	emit a soft rejection note documenting the gap. Operators see
//	zero provenance links written and a clear note in the run
//	output. When/if a legacy enrichment pass adds chunk-level
//	provenance, only the bolt reader's Cypher needs to change — the
//	mapper, apply, tests, and CLI wiring are already in place.
type ProvenanceLink struct {
	SourceLegacyID string         // "legacy:entity:<id>" OR "legacy:edge:<id>"
	ChunkLegacyID  string         // "legacy:chunk:<int64>"
	Confidence     float32        // 0.0–1.0; default 1.0 if legacy didn't track
	Properties     map[string]any // opaque extras (not currently forwarded — see godoc)
}

// QdrantReader is the legacy-Qdrant subset for Phase 6. Tests inject a
// mock; production uses the qdrant-go-client-backed QdrantClient.
//
// FetchPoints reads a batch of points from a single legacy collection
// by their UUID-string ids, returning the raw vector + the embedding
// model from the payload (or an empty model when absent). Points that
// don't exist in the collection are simply omitted from the returned
// slice; callers correlate by point id and emit rejection notes for the
// gap. The implementation MUST request `with_vectors=true` and either
// `with_payload=true` (or false — apply doesn't need the payload here
// because the model name is already known from postgres).
type QdrantReader interface {
	FetchPoints(ctx context.Context, collection string, pointIDs []string) ([]LegacyEmbeddingPoint, error)
}



