package legacy

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// FilesystemReader is the legacy on-disk filesystem subset for Phase 4.
// Production uses LocalFilesystem (rooted at LEGACY_DOCS_DIR); tests use
// FilesystemMock with an in-memory map.
type FilesystemReader interface {
	// Open returns a ReadCloser for the legacy file referenced by
	// `path`. `path` is the legacy `documents.file_path` column verbatim
	// — implementations decide how to resolve it (LocalFilesystem joins
	// against its Root). The returned size is bytes-on-disk and may
	// differ from the legacy `documents.file_size` when the legacy row
	// is stale; callers may emit a soft note on mismatch.
	//
	// Callers MUST Close the ReadCloser, even on error returned later.
	Open(ctx context.Context, path string) (io.ReadCloser, int64, error)
}

// LocalFilesystem implements FilesystemReader against the host file
// system rooted at Root. Paths that resolve outside Root after
// filepath.Clean() are rejected to prevent legacy DB rows from reading
// arbitrary files. Absolute legacy paths are tolerated only when they
// already live inside Root.
type LocalFilesystem struct {
	Root string // LEGACY_DOCS_DIR
}

// Open joins p against Root and opens the file. Returns the file size
// from os.Stat alongside the ReadCloser so callers can sanity-check the
// legacy row's `file_size` value.
func (l *LocalFilesystem) Open(_ context.Context, p string) (io.ReadCloser, int64, error) {
	if l == nil {
		return nil, 0, errors.New("legacy: LocalFilesystem is nil")
	}
	if l.Root == "" {
		return nil, 0, errors.New("legacy: LocalFilesystem.Root is empty")
	}
	if p == "" {
		return nil, 0, errors.New("legacy: filesystem path is empty")
	}

	root, err := filepath.Abs(l.Root)
	if err != nil {
		return nil, 0, fmt.Errorf("legacy: resolve root %q: %w", l.Root, err)
	}

	var resolved string
	if filepath.IsAbs(p) {
		resolved = filepath.Clean(p)
	} else {
		resolved = filepath.Clean(filepath.Join(root, p))
	}

	// Reject any path that escapes Root after Clean. Compare with a
	// trailing separator to avoid `/foo/barx` slipping past a `/foo/bar`
	// prefix check.
	rootWithSep := root
	if !strings.HasSuffix(rootWithSep, string(os.PathSeparator)) {
		rootWithSep += string(os.PathSeparator)
	}
	if resolved != root && !strings.HasPrefix(resolved, rootWithSep) {
		return nil, 0, fmt.Errorf("legacy: path %q escapes root %q", p, l.Root)
	}

	info, err := os.Stat(resolved)
	if err != nil {
		return nil, 0, fmt.Errorf("legacy: stat %q: %w", resolved, err)
	}
	if info.IsDir() {
		return nil, 0, fmt.Errorf("legacy: %q is a directory", resolved)
	}

	f, err := os.Open(resolved) //nolint:gosec // path is constrained to Root above
	if err != nil {
		return nil, 0, fmt.Errorf("legacy: open %q: %w", resolved, err)
	}
	return f, info.Size(), nil
}

// FilesystemMock is an in-memory FilesystemReader for tests.
type FilesystemMock struct {
	// Files maps legacy path → file bytes. Missing keys yield ErrNotExist.
	Files map[string][]byte
	// OpenErr, when non-nil, is returned for every Open regardless of path.
	OpenErr error
}

// Open returns a ReadCloser over the configured bytes. Returns
// ErrNotExist when the path is absent.
func (m *FilesystemMock) Open(_ context.Context, p string) (io.ReadCloser, int64, error) {
	if m.OpenErr != nil {
		return nil, 0, m.OpenErr
	}
	body, ok := m.Files[p]
	if !ok {
		return nil, 0, fmt.Errorf("filesystem-mock: %w: %s", os.ErrNotExist, p)
	}
	return io.NopCloser(strings.NewReader(string(body))), int64(len(body)), nil
}


