--- services/migrator-files/internal/legacy/memgraph.go (392 lines) ---
package legacy

import (
	"context"
	"fmt"
	"time"

	"github.com/neo4j/neo4j-go-driver/v5/neo4j"
)

// MemgraphReader is the interface the apply phases depend on.
// Tests inject a mock; production uses the bolt driver impl.
type MemgraphReader interface {
	// ListEntityTypes returns the distinct e.type values for entities
	// belonging to the given legacy organization_id.
	ListEntityTypes(ctx context.Context, legacyOrgID int) ([]EntityType, error)

	// ListRelationshipTypes returns the distinct relationship types
	// observed on edges between entities of the given org.
	ListRelationshipTypes(ctx context.Context, legacyOrgID int) ([]RelationshipType, error)

	// ListEntities returns every `:Entity` node belonging to the given
	// legacy organization_id. The returned slice is ordered by the
	// Memgraph internal node id ASC so re-runs are deterministic.
	//
	// LegacyID is synthesized as "legacy:entity:<int64>" from the
	// Memgraph internal node id (legacy storage has no stable
	// per-row id). Phase 7 persists the LegacyID → new UUID map to
	// entity_map.json so Phase 8/9 can translate references.
	ListEntities(ctx context.Context, legacyOrgID int) ([]LegacyEntity, error)

	// ListEdges returns every Memgraph relationship between two
	// `:Entity` nodes belonging to the given legacy organization_id.
	// The returned slice is ordered by the Memgraph internal
	// relationship id ASC so re-runs are deterministic.
	//
	// Per-row LegacyID is synthesized as "legacy:edge:<int64>" from
	// the Memgraph internal relationship id (legacy storage has no
	// stable per-row id on edges either). SourceLegacyID and
	// TargetLegacyID are minted from id(a) / id(b) so they line up
	// with Phase 7's LegacyEntity.LegacyID — that lets Phase 8 map
	// endpoints through entity_map.json without touching Memgraph
	// again.
	ListEdges(ctx context.Context, legacyOrgID int) ([]LegacyEdge, error)

	// ListEntityProvenance returns entity↔chunk provenance links for
	// the given legacy organization_id.
	//
	// LEGACY GAP (see ProvenanceLink godoc): legacy stores
	// entity↔Document provenance via (:Entity)-[:MENTIONED_IN]->(:Document)
	// in Memgraph; there is NO entity↔chunk granularity in the legacy
	// schema. The bolt impl therefore returns an empty slice with no
	// error — Phase 9 apply emits a single deferred-provenance note
	// documenting the gap. The interface is kept on MemgraphReader so
	// future enrichment (or a different legacy source) can drop in a
	// real implementation without API churn.
	ListEntityProvenance(ctx context.Context, legacyOrgID int) ([]ProvenanceLink, error)

	// ListEdgeProvenance returns edge↔chunk provenance links for the
	// given legacy organization_id.
	//
	// LEGACY GAP: edges in legacy may carry a `source_document_id`
	// property but never `source_chunk_id`. Edge↔chunk granularity is
	// not derivable from legacy without a fan-out heuristic that
	// would corrupt confidence scoring. The bolt impl therefore
	// returns an empty slice with no error — same contract as
	// ListEntityProvenance.
	ListEdgeProvenance(ctx context.Context, legacyOrgID int) ([]ProvenanceLink, error)

	Close(ctx context.Context) error
}

// memgraphBolt is the production driver impl.
type memgraphBolt struct {
	driver neo4j.DriverWithContext
}

// DialMemgraph opens a bolt connection to legacy Memgraph.
func DialMemgraph(ctx context.Context, uri, user, password string) (MemgraphReader, error) {
	var auth neo4j.AuthToken
	if user == "" && password == "" {
		auth = neo4j.NoAuth()
	} else {
		auth = neo4j.BasicAuth(user, password, "")
	}
	drv, err := neo4j.NewDriverWithContext(uri, auth)
	if err != nil {
		return nil, fmt.Errorf("memgraph dial: %w", err)
	}
	if err := drv.VerifyConnectivity(ctx); err != nil {
		_ = drv.Close(ctx)
		return nil, fmt.Errorf("memgraph verify: %w", err)
	}
	return &memgraphBolt{driver: drv}, nil
}

func (m *memgraphBolt) Close(ctx context.Context) error {
	return m.driver.Close(ctx)
}

func (m *memgraphBolt) ListEntityTypes(ctx context.Context, legacyOrgID int) ([]EntityType, error) {
	session := m.driver.NewSession(ctx, neo4j.SessionConfig{AccessMode: neo4j.AccessModeRead})
	defer func() { _ = session.Close(ctx) }()

	res, err := session.ExecuteRead(ctx, func(tx neo4j.ManagedTransaction) (any, error) {
		result, err := tx.Run(ctx,
			"MATCH (e:Entity {organization_id: $org}) "+
				"RETURN DISTINCT e.type AS type_name "+
				"ORDER BY type_name",
			map[string]any{"org": legacyOrgID},
		)
		if err != nil {
			return nil, err
		}
		var types []EntityType
		for result.Next(ctx) {
			rec := result.Record()
			v, _ := rec.Get("type_name")
			name, _ := v.(string)
			if name == "" {
				continue
			}
			types = append(types, EntityType{
				Name:     name,
				LegacyID: fmt.Sprintf("legacy:entity-type:%d:%s", legacyOrgID, name),
			})
		}
		return types, result.Err()
	})
	if err != nil {
		return nil, err
	}
	if res == nil {
		return nil, nil
	}
	return res.([]EntityType), nil
}

// ListEntities reads every `:Entity` node belonging to legacyOrgID and
// returns one LegacyEntity per row. Ordered by Memgraph internal node
// id ASC for deterministic re-runs.
//
// The legacy storage shape (set by graph_service.create_or_merge_entity)
// has no stable per-row id — we synthesize "legacy:entity:<int64>" from
// id(e). The natural-key fields name/type/organization_id are stripped
// from `properties(e)` and lifted into dedicated LegacyEntity columns.
// All remaining properties are surfaced opaquely via Properties.
//
// `created` is exposed as time.Time (UTC). Memgraph returns the value
// as a neo4j.LocalDateTime when present; we coerce it via
// time.Time(...). Absent values yield a zero-valued time.Time.
func (m *memgraphBolt) ListEntities(ctx context.Context, legacyOrgID int) ([]LegacyEntity, error) {
	session := m.driver.NewSession(ctx, neo4j.SessionConfig{AccessMode: neo4j.AccessModeRead})
	defer func() { _ = session.Close(ctx) }()

	res, err := session.ExecuteRead(ctx, func(tx neo4j.ManagedTransaction) (any, error) {
		result, err := tx.Run(ctx,
			"MATCH (e:Entity {organization_id: $org}) "+
				"RETURN id(e) AS internal_id, "+
				"       e.name AS name, "+
				"       e.type AS type_name, "+
				"       e.created AS created, "+
				"       properties(e) AS props "+
				"ORDER BY internal_id ASC",
			map[string]any{"org": legacyOrgID},
		)
		if err != nil {
			return nil, err
		}
		var entities []LegacyEntity
		for result.Next(ctx) {
			rec := result.Record()
			internalID, _ := rec.Get("internal_id")
			intID, _ := internalID.(int64)
			nameAny, _ := rec.Get("name")
			name, _ := nameAny.(string)
			typeAny, _ := rec.Get("type_name")
			typeName, _ := typeAny.(string)

			// `created` may be a neo4j.LocalDateTime or absent.
			var createdAt time.Time
			if v, ok := rec.Get("created"); ok && v != nil {
				if ldt, isLDT := v.(neo4j.LocalDateTime); isLDT {
					createdAt = time.Time(ldt)
				} else if t, isTime := v.(time.Time); isTime {
					createdAt = t
				}
			}

			// `properties(e)` gives the full map; strip the natural-key
			// fields we already lifted out + book-keeping fields the
			// new platform doesn't carry over.
			propsAny, _ := rec.Get("props")
			rawProps, _ := propsAny.(map[string]any)
			props := make(map[string]any, len(rawProps))
			for k, v := range rawProps {
				switch k {
				case "name", "type", "organization_id", "created":
					// already lifted into dedicated columns
					continue
				}
				props[k] = v
			}

			entities = append(entities, LegacyEntity{
				LegacyID:    fmt.Sprintf("legacy:entity:%d", intID),
				Label:       name,
				TypeName:    typeName,
				Description: "", // legacy stores no description
				Properties:  props,
				CreatedAt:   createdAt,
				// LegacyCorpusIDs intentionally nil — see godoc on
				// LegacyEntity. Corpus join is Phase 9 territory.
			})
		}
		return entities, result.Err()
	})
	if err != nil {
		return nil, err
	}
	if res == nil {
		return nil, nil
	}
	return res.([]LegacyEntity), nil
}

// ListEdges reads every Memgraph relationship between two `:Entity`
// nodes belonging to legacyOrgID and returns one LegacyEdge per row.
// Ordered by the Memgraph internal relationship id ASC for deterministic
// re-runs.
//
// The legacy storage shape (set by graph_service.create_relationship)
// has no stable per-row id on edges — we synthesize:
//
//	LegacyID       = "legacy:edge:<id(r)>"
//	SourceLegacyID = "legacy:entity:<id(a)>"
//	TargetLegacyID = "legacy:entity:<id(b)>"
//
// matching the synthetic ids Phase 7 minted for LegacyEntity. The
// relationship label (type(r)) is forwarded verbatim — Phase 2 already
// bootstrapped each distinct value into files.relationship_types,
// keyed by "legacy:rel-type:<orgID>:<name>", so the mapper resolves
// it via that sidecar.
//
// `created` is exposed as time.Time (UTC). Memgraph returns the value
// as a neo4j.LocalDateTime when present; we coerce it via
// time.Time(...). Absent values yield a zero-valued time.Time.
func (m *memgraphBolt) ListEdges(ctx context.Context, legacyOrgID int) ([]LegacyEdge, error) {
	session := m.driver.NewSession(ctx, neo4j.SessionConfig{AccessMode: neo4j.AccessModeRead})
	defer func() { _ = session.Close(ctx) }()

	res, err := session.ExecuteRead(ctx, func(tx neo4j.ManagedTransaction) (any, error) {
		result, err := tx.Run(ctx,
			"MATCH (a:Entity {organization_id: $org})-[r]->(b:Entity {organization_id: $org}) "+
				"RETURN id(a) AS source_id, "+
				"       id(b) AS target_id, "+
				"       id(r) AS edge_id, "+
				"       type(r) AS relationship_type, "+
				"       properties(r) AS props "+
				"ORDER BY edge_id ASC",
			map[string]any{"org": legacyOrgID},
		)
		if err != nil {
			return nil, err
		}
		var edges []LegacyEdge
		for result.Next(ctx) {
			rec := result.Record()
			srcAny, _ := rec.Get("source_id")
			srcID, _ := srcAny.(int64)
			tgtAny, _ := rec.Get("target_id")
			tgtID, _ := tgtAny.(int64)
			edgeAny, _ := rec.Get("edge_id")
			edgeID, _ := edgeAny.(int64)
			relAny, _ := rec.Get("relationship_type")
			relType, _ := relAny.(string)

			// `properties(r)` includes everything; lift `created`
			// out and strip it from the opaque props bag.
			propsAny, _ := rec.Get("props")
			rawProps, _ := propsAny.(map[string]any)

			var createdAt time.Time
			if v, ok := rawProps["created"]; ok && v != nil {
				if ldt, isLDT := v.(neo4j.LocalDateTime); isLDT {
					createdAt = time.Time(ldt)
				} else if t, isTime := v.(time.Time); isTime {
					createdAt = t
				}
			}

			props := make(map[string]any, len(rawProps))
			for k, v := range rawProps {
				if k == "created" {
					continue
				}
				props[k] = v
			}

			edges = append(edges, LegacyEdge{
				LegacyID:         fmt.Sprintf("legacy:edge:%d", edgeID),
				SourceLegacyID:   fmt.Sprintf("legacy:entity:%d", srcID),
				TargetLegacyID:   fmt.Sprintf("legacy:entity:%d", tgtID),
				RelationshipType: relType,
				Properties:       props,
				CreatedAt:        createdAt,
			})
		}
		return edges, result.Err()
	})
	if err != nil {
		return nil, err
	}
	if res == nil {
		return nil, nil
	}
	return res.([]LegacyEdge), nil
}

// ListEntityProvenance returns entity↔chunk provenance links.
//
// Legacy stores entity↔Document provenance via the
// (:Entity)-[:MENTIONED_IN]->(:Document) edge — Document.document_id
// is the legacy `documents.id` (Postgres). The new platform's
// MigrateProvenance API requires entity↔CHUNK granularity which is
// not derivable from legacy without a wildly imprecise fan-out (one
// MENTIONED_IN → every chunk of that document). We deliberately
// return an empty slice and let Phase 9 apply emit a note. See
// ProvenanceLink godoc + this file's interface comment for the full
// rationale.
//
// When the legacy data is later enriched with chunk-level
// provenance, this method's body becomes the only place that needs
// the new Cypher; the rest of Phase 9 (mapper, apply, sidecar
// consumption, CLI wiring) is already in place.
func (m *memgraphBolt) ListEntityProvenance(ctx context.Context, legacyOrgID int) ([]ProvenanceLink, error) {
	_ = ctx
	_ = legacyOrgID
	return nil, nil
}

// ListEdgeProvenance returns edge↔chunk provenance links.
//
// Same gap as ListEntityProvenance: edges may carry
// `source_document_id` (an int FK to legacy `documents.id`) but
// never reference a chunk. Returning empty + emitting a note is the
// honest answer until a chunk-level enrichment ships.
func (m *memgraphBolt) ListEdgeProvenance(ctx context.Context, legacyOrgID int) ([]ProvenanceLink, error) {
	_ = ctx
	_ = legacyOrgID
	return nil, nil
}

func (m *memgraphBolt) ListRelationshipTypes(ctx context.Context, legacyOrgID int) ([]RelationshipType, error) {
	session := m.driver.NewSession(ctx, neo4j.SessionConfig{AccessMode: neo4j.AccessModeRead})
	defer func() { _ = session.Close(ctx) }()

	res, err := session.ExecuteRead(ctx, func(tx neo4j.ManagedTransaction) (any, error) {
		result, err := tx.Run(ctx,
			"MATCH (s:Entity {organization_id: $org})-[r]->(t:Entity {organization_id: $org}) "+
				"RETURN DISTINCT type(r) AS rel_name "+
				"ORDER BY rel_name",
			map[string]any{"org": legacyOrgID},
		)
		if err != nil {
			return nil, err
		}
		var rels []RelationshipType
		for result.Next(ctx) {
			rec := result.Record()
			v, _ := rec.Get("rel_name")
			name, _ := v.(string)
			if name == "" {
				continue
			}
			rels = append(rels, RelationshipType{
				Name:       name,
				IsDirected: true, // all legacy edges are directed
				LegacyID:   fmt.Sprintf("legacy:rel-type:%d:%s", legacyOrgID, name),
			})
		}
		return rels, result.Err()
	})
	if err != nil {
		return nil, err
	}
	if res == nil {
		return nil, nil
	}
	return res.([]RelationshipType), nil
}


