package legacy

import (
	"context"
	"errors"
	"fmt"
	"io"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/credentials"
	"github.com/aws/aws-sdk-go-v2/service/s3"
)

// ObjectWriter is the write side of the new-platform object store. The
// migrator only needs PUT — it never reads back from MinIO. Tests inject
// S3Mock; production wires S3Writer over aws-sdk-go-v2/service/s3
// configured for MinIO (path-style, us-east-1).
type ObjectWriter interface {
	Put(ctx context.Context, bucket, key string, body io.Reader, contentType string, sizeBytes int64) error
}

// S3Writer is the production ObjectWriter backed by aws-sdk-go-v2's S3
// client pointed at the new MinIO endpoint.
type S3Writer struct {
	client *s3.Client
}

// NewS3Writer constructs an S3 client against the given MinIO endpoint.
// Path-style addressing is required for MinIO; region is fixed to
// us-east-1 to match files-bff and the MinIO defaults.
func NewS3Writer(_ context.Context, endpoint, accessKey, secretKey string) (*S3Writer, error) {
	if endpoint == "" {
		return nil, errors.New("legacy: minio endpoint required")
	}
	if accessKey == "" || secretKey == "" {
		return nil, errors.New("legacy: minio access/secret keys required")
	}
	client := s3.New(s3.Options{
		Region:       "us-east-1",
		Credentials:  credentials.NewStaticCredentialsProvider(accessKey, secretKey, ""),
		BaseEndpoint: aws.String(endpoint),
		UsePathStyle: true,
	})
	return &S3Writer{client: client}, nil
}

// Put streams body into bucket/key with the given content-type. sizeBytes
// is informational; the SDK reads to EOF regardless. We pass it through
// to ContentLength so the AWS SDK can produce a single-shot PUT instead
// of a multipart upload for small documents (legacy docs are typically
// <50MB).
func (w *S3Writer) Put(ctx context.Context, bucket, key string, body io.Reader, contentType string, sizeBytes int64) error {
	if w == nil || w.client == nil {
		return errors.New("legacy: S3Writer not initialized")
	}
	if bucket == "" {
		return errors.New("legacy: bucket required")
	}
	if key == "" {
		return errors.New("legacy: key required")
	}
	in := &s3.PutObjectInput{
		Bucket: aws.String(bucket),
		Key:    aws.String(key),
		Body:   body,
	}
	if contentType != "" {
		in.ContentType = aws.String(contentType)
	}
	if sizeBytes > 0 {
		in.ContentLength = aws.Int64(sizeBytes)
	}
	if _, err := w.client.PutObject(ctx, in); err != nil {
		return fmt.Errorf("legacy: minio put %s/%s: %w", bucket, key, err)
	}
	return nil
}

// PutCall captures one ObjectWriter.Put invocation for assertions.
type PutCall struct {
	Bucket      string
	Key         string
	Body        []byte
	ContentType string
	SizeBytes   int64
}

// S3Mock is an in-memory ObjectWriter for tests.
type S3Mock struct {
	Puts   []PutCall
	PutErr error
}

// Put records the call and returns PutErr (or nil).
func (m *S3Mock) Put(_ context.Context, bucket, key string, body io.Reader, contentType string, sizeBytes int64) error {
	if m.PutErr != nil {
		return m.PutErr
	}
	buf, err := io.ReadAll(body)
	if err != nil {
		return fmt.Errorf("s3-mock: drain body: %w", err)
	}
	m.Puts = append(m.Puts, PutCall{
		Bucket:      bucket,
		Key:         key,
		Body:        buf,
		ContentType: contentType,
		SizeBytes:   sizeBytes,
	})
	return nil
}


