package legacy

import (
	"context"
	"errors"
	"fmt"

	"github.com/jackc/pgx/v5/pgxpool"
)

// PostgresReader reads from the legacy OmniCore monolith Postgres. It
// is strictly read-only — no INSERT/UPDATE/DELETE methods exist on this
// type. Production deployments should connect with the migrator_ro role
// to enforce that at the database level too.
//
// Connection management is delegated to pgxpool.Pool; the migrator
// process holds one PostgresReader for the duration of a run.
type PostgresReader struct {
	pool *pgxpool.Pool
}

// NewPostgresReader opens a pgxpool against the legacy DSN. Callers
// must defer Close() — pgxpool will leak goroutines otherwise.
func NewPostgresReader(ctx context.Context, dsn string) (*PostgresReader, error) {
	if dsn == "" {
		return nil, errors.New("legacy: postgres dsn required")
	}
	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		return nil, fmt.Errorf("legacy: open postgres pool: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("legacy: ping postgres: %w", err)
	}
	return &PostgresReader{pool: pool}, nil
}

// Close releases the underlying connection pool. Safe to call multiple
// times.
func (r *PostgresReader) Close() {
	if r.pool != nil {
		r.pool.Close()
	}
}

// queryDocumentCollectionsByOrg is the SQL for Phase 3's read. NULL
// description is coalesced to '' so the mapper does not have to deal
// with sql.NullString.
const queryDocumentCollectionsByOrg = `
SELECT id, name, COALESCE(description, ''), visibility, user_id, created_at
  FROM document_collections
 WHERE organization_id = $1
 ORDER BY id`

// queryDocumentsByOrg is the SQL for Phase 4's read. NULL columns that
// would force callers into sql.Null* shenanigans are coalesced server-
// side. file_type is the legacy "pdf"/"docx"/etc. tag; the mapper
// translates to a real RFC-6838 mime type. uploaded_by is nullable —
// pgx handles that natively into *int64.
const queryDocumentsByOrg = `
SELECT id,
       collection_id,
       COALESCE(file_path, ''),
       COALESCE(filename, COALESCE(title, '')),
       COALESCE(file_type, ''),
       COALESCE(file_size, 0),
       uploaded_by,
       created_at
  FROM documents
 WHERE organization_id = $1
 ORDER BY id`

// ListCorpora returns every legacy document_collections row scoped to
// the given legacy organization_id (INTEGER FK to legacy organizations).
// Order is stable on `id ASC` so apply re-runs walk rows in the same
// order on every invocation.
func (r *PostgresReader) ListCorpora(ctx context.Context, legacyOrgID int64) ([]LegacyCorpus, error) {
	if legacyOrgID <= 0 {
		return nil, fmt.Errorf("legacy: invalid org id %d", legacyOrgID)
	}
	rows, err := r.pool.Query(ctx, queryDocumentCollectionsByOrg, legacyOrgID)
	if err != nil {
		return nil, fmt.Errorf("legacy: list document_collections org=%d: %w", legacyOrgID, err)
	}
	defer rows.Close()

	var out []LegacyCorpus
	for rows.Next() {
		var lc LegacyCorpus
		var owner *int64
		if err := rows.Scan(&lc.LegacyID, &lc.Name, &lc.Description, &lc.Visibility, &owner, &lc.CreatedAt); err != nil {
			return nil, fmt.Errorf("legacy: scan document_collections row: %w", err)
		}
		lc.OwnerUserID = owner
		out = append(out, lc)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("legacy: iterate document_collections rows: %w", err)
	}
	return out, nil
}

// queryChunksByDocument is the SQL for Phase 5's read. Stable column
// list (never SELECT *) — the legacy table has embedding_id /
// embedding_model / embedding_dimension columns we deliberately ignore
// here (Phase 6 handles embeddings). chunk_metadata is also dropped;
// the new platform's per-row schema doesn't carry it. start_char and
// end_char are nullable in legacy and pass through as *int32.
const queryChunksByDocument = `
SELECT id,
       document_id,
       chunk_index,
       content,
       start_char,
       end_char,
       created_at
  FROM document_chunks
 WHERE document_id = $1
 ORDER BY chunk_index ASC, id ASC`

// queryEmbeddingRefsByDocument is the SQL for Phase 6's read. Joins
// `document_chunks` with `documents` to reach `document_collections`
// for the per-corpus `vector_collection_name`. Rows with NULL/empty
// chroma_id or empty collection name are dropped server-side — they
// have no legacy Qdrant point to copy. embedding_model is coalesced
// to '' (legacy fixtures occasionally lack it; the proto field is
// informational and an empty string is acceptable downstream).
const queryEmbeddingRefsByDocument = `
SELECT dc.id,
       dc.document_id,
       dc.chroma_id,
       COALESCE(dc.embedding_model, ''),
       col.vector_collection_name
  FROM document_chunks dc
  JOIN documents d ON d.id = dc.document_id
  JOIN document_collections col ON col.id = d.collection_id
 WHERE dc.document_id = $1
   AND dc.chroma_id IS NOT NULL
   AND dc.chroma_id <> ''
   AND col.vector_collection_name <> ''
 ORDER BY dc.chunk_index ASC, dc.id ASC`

// ListEmbeddingRefsByDocument returns every legacy `document_chunks`
// row for a single legacy document id that has a non-empty chroma_id,
// each joined with its corpus' `vector_collection_name`. Phase 6's
// apply layer iterates this per (legacy_doc_id, new_doc_uuid) pair.
//
// Rows are ordered by chunk_index ASC (id ASC tiebreaker) — same
// ordering as Phase 5, so per-document re-runs walk in a stable order.
func (r *PostgresReader) ListEmbeddingRefsByDocument(ctx context.Context, legacyDocumentID int64) ([]LegacyChunkEmbeddingRef, error) {
	if legacyDocumentID <= 0 {
		return nil, fmt.Errorf("legacy: invalid document id %d", legacyDocumentID)
	}
	rows, err := r.pool.Query(ctx, queryEmbeddingRefsByDocument, legacyDocumentID)
	if err != nil {
		return nil, fmt.Errorf("legacy: list embedding refs doc=%d: %w", legacyDocumentID, err)
	}
	defer rows.Close()

	var out []LegacyChunkEmbeddingRef
	for rows.Next() {
		var ref LegacyChunkEmbeddingRef
		if err := rows.Scan(
			&ref.LegacyChunkID,
			&ref.LegacyDocumentID,
			&ref.ChromaID,
			&ref.EmbeddingModel,
			&ref.VectorCollectionName,
		); err != nil {
			return nil, fmt.Errorf("legacy: scan embedding ref row: %w", err)
		}
		out = append(out, ref)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("legacy: iterate embedding ref rows: %w", err)
	}
	return out, nil
}

// ListChunksByDocument returns every legacy `document_chunks` row for a
// single legacy document id, ordered by chunk_index ASC (id ASC as a
// tiebreaker for legacy data with stale duplicate indexes). Phase 5's
// apply layer iterates this per (legacy_doc_id, new_doc_uuid) pair from
// the document_legacy_id_map sidecar.
func (r *PostgresReader) ListChunksByDocument(ctx context.Context, legacyDocumentID int64) ([]LegacyChunk, error) {
	if legacyDocumentID <= 0 {
		return nil, fmt.Errorf("legacy: invalid document id %d", legacyDocumentID)
	}
	rows, err := r.pool.Query(ctx, queryChunksByDocument, legacyDocumentID)
	if err != nil {
		return nil, fmt.Errorf("legacy: list document_chunks doc=%d: %w", legacyDocumentID, err)
	}
	defer rows.Close()

	var out []LegacyChunk
	for rows.Next() {
		var lc LegacyChunk
		var startChar, endChar *int32
		if err := rows.Scan(
			&lc.LegacyID,
			&lc.LegacyDocumentID,
			&lc.ChunkIndex,
			&lc.Content,
			&startChar,
			&endChar,
			&lc.CreatedAt,
		); err != nil {
			return nil, fmt.Errorf("legacy: scan document_chunks row: %w", err)
		}
		lc.StartChar = startChar
		lc.EndChar = endChar
		out = append(out, lc)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("legacy: iterate document_chunks rows: %w", err)
	}
	return out, nil
}

// ListDocuments returns every legacy `documents` row scoped to the given
// legacy organization_id. Order is stable on `id ASC` so apply re-runs
// walk rows in the same order on every invocation. uploaded_by is left
// as *int64 (nullable in legacy) — the mapper emits a rejection note
// when it is nil because files-svc's MigrateUpload requires a non-
// empty uploaded_by.
func (r *PostgresReader) ListDocuments(ctx context.Context, legacyOrgID int64) ([]LegacyDocument, error) {
	if legacyOrgID <= 0 {
		return nil, fmt.Errorf("legacy: invalid org id %d", legacyOrgID)
	}
	rows, err := r.pool.Query(ctx, queryDocumentsByOrg, legacyOrgID)
	if err != nil {
		return nil, fmt.Errorf("legacy: list documents org=%d: %w", legacyOrgID, err)
	}
	defer rows.Close()

	var out []LegacyDocument
	for rows.Next() {
		var ld LegacyDocument
		var owner *int64
		if err := rows.Scan(
			&ld.LegacyID,
			&ld.LegacyCollectionID,
			&ld.FilePath,
			&ld.OriginalFilename,
			&ld.MIMEType,
			&ld.SizeBytes,
			&owner,
			&ld.CreatedAt,
		); err != nil {
			return nil, fmt.Errorf("legacy: scan documents row: %w", err)
		}
		ld.UploadedBy = owner
		out = append(out, ld)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("legacy: iterate documents rows: %w", err)
	}
	return out, nil
}


