package legacy

import "context"

// QdrantMock is a deterministic in-memory QdrantReader for tests.
// Apply tests import it directly without ceremony. Points are
// indexed by (collection, point_id). Missing points (id absent from
// the map) are silently dropped — mirroring the production behavior
// of "point not found" being a non-error empty result.
type QdrantMock struct {
	// Points is keyed first by collection name, then by point id.
	// Test fixtures populate this directly.
	Points map[string]map[string]LegacyEmbeddingPoint

	// FetchErr lets a test trigger a hard failure on the next
	// FetchPoints call. Cleared automatically — set per call.
	FetchErr error
}

// FetchPoints returns the configured points for the given collection
// and ids, or FetchErr if set. Order of results matches the input id
// order, with missing ids omitted.
func (m *QdrantMock) FetchPoints(_ context.Context, collection string, pointIDs []string) ([]LegacyEmbeddingPoint, error) {
	if m.FetchErr != nil {
		return nil, m.FetchErr
	}
	if m.Points == nil {
		return nil, nil
	}
	col, ok := m.Points[collection]
	if !ok {
		return nil, nil
	}
	out := make([]LegacyEmbeddingPoint, 0, len(pointIDs))
	for _, id := range pointIDs {
		if p, ok := col[id]; ok {
			out = append(out, p)
		}
	}
	return out, nil
}


